            guard parts.count >= 3, let x = Double(parts[0]), let y = Double(parts[1]), let d = Double(parts[2]) else { continue }
            let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
            app.activate()
            app.coordinate(withNormalizedOffset: CGVector(dx: x, dy: y)).tap()
            Thread.sleep(forTimeInterval: d)
        }
    }
}
